-- Browser sessions can read owned sensor metadata, but never device key hashes
-- and cannot create, update, or delete sensor credentials directly.
drop policy if exists "users manage own sensors" on public.sensors;
drop policy if exists "users read own sensors" on public.sensors;
create policy "users read own sensors" on public.sensors
  for select to authenticated using (auth.uid() = user_id);
revoke all on public.sensors from anon, authenticated;
grant select (id, user_id, plant_id, name, last_seen_at, created_at)
  on public.sensors to authenticated;

-- Alerts are generated by trusted server-side ingestion, not by browser clients.
drop policy if exists "users manage own alerts" on public.alerts;
drop policy if exists "users read own alerts" on public.alerts;
create policy "users read own alerts" on public.alerts
  for select to authenticated using (auth.uid() = user_id);
revoke all on public.alerts from anon, authenticated;
grant select on public.alerts to authenticated;

-- The browser cannot write or delete sensor history. The Render service role
-- writes readings through the device-key endpoint.
revoke insert, update, delete on public.readings from anon, authenticated;
